INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2074, 'រកចំនួនគត់ពីរខ្ទង់តូចបំផុតដែលចែកដាច់នឹង \(4\) ផង \(6\) ផង និង \(9\) ផង។', NULL, '[]', 0, NULL, 5, 'writing', '\(4 = 2^2, 6 = 2 \times 3, 9 = 3^2\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2075, 'សិស្សថ្នាក់ទី ៧ មាន \(36\) នាក់ និងថ្នាក់ទី ៨ មាន \(48\) នាក់ ត្រូវចែកជាក្រុមស្មើៗគ្នា ដោយមិនលាយថ្នាក់ ហើយក្រុមធំបំផុត។ ក. ក្រុមមួយមានសិស្សប៉ុន្មាននាក់? ខ. មានក្រុមសរុបប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ទំហំក្រុម \(= GCD(36, 48) = 12\) នាក់ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2076, 'ហាងបីដាក់ថ្លៃទំនិញថ្មីរៀងរាល់ \(4\) ថ្ងៃ \(6\) ថ្ងៃ និង \(10\) ថ្ងៃ។ នៅថ្ងៃទី \(1\) ហាងទាំងបីដាក់ថ្លៃថ្មីព្រមគ្នា។ ក. ក្រោយប៉ុន្មានថ្ងៃទើបដាក់ព្រមគ្នាម្តងទៀត? ខ. ក្នុងរយៈពេល \(180\) ថ្ងៃបន្ទាប់ពីថ្ងៃទី \(1\) ដាក់ព្រមគ្នាបន្ថែមប៉ុន្មានដង?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(LCM(4, 6, 10) = 60\) ថ្ងៃ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2077, 'ក្រណាត់ផ្ទាំងមួយចតុកោណកែង \(60\ \text{cm}\) គុណ \(84\ \text{cm}\) ត្រូវកាត់ជាការ៉េប៉ុនៗគ្នាធំបំផុតមិនឱ្យសល់ក្រណាត់។ ក. រកជ្រុងការ៉េ។ ខ. កាត់បានប៉ុន្មានការ៉េ? គ. បើការ៉េមួយលក់ \(1\,500\) ៛ ទទួលបានប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(GCD(60, 84) = 12\ \text{cm}\) (2 ពិន្ទុ)
